fn findMax(a: &[i32], n: usize) -> usize {
    // We assume n >= 1 and n <= a.len(), so index 0 is valid.
    let mut max_idx = 0;
    for i in 1..n {
        if a[i] > a[max_idx] {
            max_idx = i;
        }
    }
    max_idx
}

